 * SPDX-License-Identifier: MIT
 */

import { type Request, type Response, type NextFunction } from 'express'
import { AllHtmlEntities as Entities } from 'html-entities'
import config from 'config'
import fs from 'node:fs/promises'

import * as challengeUtils from '../lib/challengeUtils'
import { themes } from '../views/themes/themes'
import { challenges } from '../data/datacache'
import * as security from '../lib/insecurity'
import { UserModel } from '../models/user'
import * as utils from '../lib/utils'

const entities = new Entities()

function favicon () {
  return utils.extractFilename(config.get('application.favicon'))
}

export function getUserProfile () {
  return async (req: Request, res: Response, next: NextFunction) => {
    let template: string
    try {
      template = await fs.readFile('views/userProfile.pug', { encoding: 'utf-8' })
    } catch (err) {
      next(err)
      return
    }

    const loggedInUser = security.authenticatedUsers.get(req.cookies.token)
    if (!loggedInUser) {
      next(new Error('Blocked illegal activity by ' + req.socket.remoteAddress)); return
    }

    let user: UserModel | null
    try {
      user = await UserModel.findByPk(loggedInUser.data.id)
    } catch (error) {
      next(error)
      return
    }

    if (!user) {
      next(new Error('Blocked illegal activity by ' + req.socket.remoteAddress))
      return
    }

    let username = user.username

    if (username?.match(/#{(.*)}/) !== null && utils.isChallengeEnabled(challenges.usernameXssChallenge)) {
      req.app.locals.abused_ssti_bug = true
      const code = username?.substring(2, username.length - 1)
      try {
        if (!code) {
          throw new Error('Username is null')
        }
        username = eval(code) // eslint-disable-line no-eval
      } catch (err) {
        username = '\\' + username
      }
    } else {
      username = '\\' + username
    }

    const themeKey = config.get<string>('application.theme') as keyof typeof themes
    const theme = themes[themeKey] || themes['bluegrey-lightgreen']

    if (username) {
      template = template.replace(/_username_/g, username)
    }
    template = template.replace(/_emailHash_/g, security.hash(user?.email))
    template = template.replace(/_title_/g, entities.encode(config.get<string>('application.name')))
    template = template.replace(/_favicon_/g, favicon())
    template = template.replace(/_bgColor_/g, theme.bgColor)
    template = template.replace(/_textColor_/g, theme.textColor)
    template = template.replace(/_navColor_/g, theme.navColor)
    template = template.replace(/_primLight_/g, theme.primLight)
    template = template.replace(/_primDark_/g, theme.primDark)
    template = template.replace(/_logo_/g, utils.extractFilename(config.get('application.logo')))

    try {
      const pug = (await import('pug')).default
      const fn = pug.compile(template)
      const CSP = `img-src 'self' ${user?.profileImage}; script-src 'self' 'unsafe-eval'`

      challengeUtils.solveIf(challenges.usernameXssChallenge, () => {
        return username && user?.profileImage.match(/;[ ]*script-src(.)*'unsafe-inline'/g) !== null && utils.contains(username, '<script>alert(`xss`)</script>')
      })

      res.set({
        'Content-Security-Policy': CSP
      })

      res.send(fn(user))
    } catch (err) {
      next(new Error('Blocked illegal activity by ' + req.socket.remoteAddress))
    }
  }
}
```

Alerta da ferramenta de analise estatica (Semgrep) que deve ser corrigido:
- Arquivo: routes/userProfile.ts
- Linha: 61
- Regra: javascript.browser.security.eval-detected.eval-detected
- CWE: CWE-95: Improper Neutralization of Directives in Dynamically Evaluated Code ('Eval Injection')
- Mensagem: Detected the use of eval(). eval() can be dangerous if used to evaluate dynamic content. If this content can be input from outside the program, this may be a code injection vulnerability. Ensure evaluated content is not definable by external sources.

Contexto técnico recuperado para apoiar a análise:
## 1. Descrição e sinais

Injeção ocorre quando um valor vira instrução. SQL, seletores NoSQL, comandos, código dinâmico, templates e XML possuem interpretadores diferentes; localizar o interpretador é o primeiro passo.

## 2. Origem e condições

Acompanhe entrada, transformações e chamada final. Um literal interno ou um valor validado pode tornar o padrão apenas suspeito. Dados de banco também podem ter origem externa. A confirmação depende da possibilidade de controlar a sintaxe interpretada.

## 3. Impactos e interpretação

O efeito pode ser acesso indevido, modificação de dados ou execução de instruções. Encontrar concatenação não estabelece explorabilidade; verificar o driver e suas opções é necessário.

## 4. Mitigação por mecanismo

### SQL
Use parâmetros para valores; nomes de tabelas e ordenações requerem seleção de identificadores permitidos.
### NoSQL
Construa seletores com campos conhecidos e valores escalares validados; receber um objeto inteiro permite operadores inesperados mesmo sem texto concatenado.
### Código, comandos e templates
Prefira operações declarativas e argumentos separados. Não execute código recebido. Um contexto de `node:vm` não constitui fronteira de segurança. Escaping de template depende do contexto de saída.
### XML e formatos
Desabilite entidades externas e resolução de recursos conforme o parser. Substituir aspas não resolve XXE; strings de formato devem ser constantes quando o interpretador as trata como instruções.

## 5. Preservação funcional

Mantenha filtros, ordenação, mensagens e resultado esperado. Não remova a consulta ou a função para eliminar o alerta. Verifique valores válidos que contêm aspas e caracteres internacionais.

## 6. Exemplo genérico

Exemplo SQL vulnerável (API abstrata de driver):
```typescript
const sql = "SELECT title FROM notes WHERE owner = '" + owner + "'";
await db.query(sql);
```
Versão com parâmetros, assumindo suporte a placeholders nesse driver:
```typescript
await db.query('SELECT title FROM notes WHERE owner = ?', [owner]);
```

## 7. Limitações e verificação

A sintaxe dos parâmetros varia entre drivers. Teste dados hostis e válidos, tipos e erro de banco. Para NoSQL/XML/código, analise o mecanismo correspondente: o exemplo SQL não prova uma mitigação universal.


Antes de responder, percorra as cinco etapas abaixo, nesta ordem:

1. Identifique a vulnerabilidade presente no código.
2. Explique a causa da vulnerabilidade: que construção do código a torna
   possível e por quê.
3. Descreva o impacto de segurança: o que um atacante consegue obter ou fazer
   explorando essa falha.
4. Proponha a correção no código.
5. Justifique tecnicamente por que a solução proposta remove ou mitiga a
   vulnerabilidade identificada.

Restricoes obrigatorias:
- Altere o minimo necessario para corrigir a vulnerabilidade. Nao refatore, nao reformate e nao renomeie nada.
- Não altere mensagens de erro, textos visíveis ao usuário, nomes de identificadores nem assinaturas de funções existentes.
- Nao altere arquivos de teste.
- Cada "trecho_original" deve ser copiado LITERALMENTE do codigo fornecido (mesmos espacos, quebras de linha e pontuacao) e deve aparecer UMA unica vez no arquivo. Inclua linhas vizinhas se precisar para torna-lo unico.
- Preserve o comportamento funcional existente.
- Em "arquivo", use exatamente o caminho relativo informado acima.

Formato da resposta: um objeto JSON com os campos
vulnerabilidade_identificada, causa_da_vulnerabilidade, estrategia_de_correcao,
edicoes (lista de {arquivo, trecho_original, trecho_corrigido}),
justificativa_tecnica e limitacoes_da_correcao.
